// Extraer y enriquecer datos de insumos críticos enviados por el backend
const body = $input.first().json.body || $input.first().json;
const insumosCriticos = body.insumos_criticos || [];
const topProductos = body.top_productos || [];

const promptContext = `
Eres el barista principal y gerente de suministros de Komorebi Café & Bakery.
Tu objetivo es analizar los insumos que están por debajo del stock mínimo de seguridad y las ventas recientes.

Insumos críticos actuales:
${JSON.stringify(insumosCriticos, null, 2)}

Top productos más vendidos:
${JSON.stringify(topProductos, null, 2)}

Genera una recomendación de compras estructurada con:
1. Cantidad sugerida para cada insumo (cubriendo déficit + 7 días de consumo).
2. Nivel de urgencia (Crítica, Alta, Media).
3. Justificación operativa del impacto en las ventas si se agota.
`;

return {
  promptContext,
  insumosCriticos,
  topProductos
};

parameters.responseBody:
={
  "ok": true,
  "data": {
    "fecha_analisis": $now.toISO(),
    "resumen_ejecutivo": "El Agente de IA analizó los insumos críticos frente al ritmo de ventas semanal. Se generaron recomendaciones de reposición prioritarias para evitar quiebre de stock en bebidas estrella.",
    "analisis_ia": $json.output || $json.text || "Análisis de inventario completado con éxito",
    "recomendaciones": $("Preparar Datos e Insumos").first().json.insumosCriticos.map(item => ({
      "insumo_id": item.id,
      "nombre": item.nombre,
      "unidad": item.unidad,
      "stock_actual": item.stock_actual,
      "stock_minimo": item.stock_minimo,
      "cantidad_sugerida": Math.round((item.deficit + item.stock_minimo * 1.5) * 100) / 100,
      "urgencia": item.stock_actual <= item.stock_minimo * 0.4 ? "Crítica" : "Alta",
      "justificacion": `El inventario de ${item.nombre} se encuentra por debajo del mínimo operativo. Se recomienda compra urgente para asegurar la producción semanal.`
    }))
  },
  "error": null
}
